 extern "C" void sort_u32(uint32_t* a, size_t n) {
+    if (n < 2) return;
+
+    // Detect sorted/reverse sorted for O(n) optimization
+    bool sorted = true;
+    bool reverse = true;
+    for (size_t i = 0; i < n - 1; ++i) {
+        if (a[i] > a[i + 1]) sorted = false;
+        if (a[i] < a[i + 1]) reverse = false;
+        if (!sorted && !reverse) break;
+    }
+    if (sorted) return;
+    if (reverse) {
+        std::reverse(a, a + n);
+        return;
+    }
+
     std::vector<uint32_t> tmp(n);
-    merge_sort_rec(a, tmp.data(), 0, n);
+    uint32_t* src = a;
+    uint32_t* dst = tmp.data();
+
+    // Combined histogram pass to reduce memory traffic
+    size_t c1[2048] = {0}, c2[2048] = {0}, c3[1024] = {0};
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t v = src[i];
+        c1[v & 0x7FF]++;
+        c2[(v >> 11) & 0x7FF]++;
+        c3[(v >> 22) & 0x3FF]++;
+    }
+
+    // Pass 1: bits 0-10
+    {
+        size_t pos[2048];
+        pos[0] = 0;
+        for (int i = 1; i < 2048; ++i) pos[i] = pos[i - 1] + c1[i - 1];
+        for (size_t i = 0; i < n; ++i) dst[pos[src[i] & 0x7FF]++] = src[i];
+        // Re-calculate prefix sums for the next pass based on the actual distribution
+        // but we need to use the counts we just used to transform.
+        // Actually, it's easier to just re-calculate prefix sums from c2 and c3.
+        std::swap(src, dst);
+    }
+
+    // Pass 2: bits 11-21
+    {
+        size_t pos[2048];
+        pos[0] = 0;
+        for (int i = 1; i < 2048; ++i) pos[i] = pos[i - 1] + c2[i - 1];
+        for (size_t i = 0; i < n; ++i) dst[pos[(src[i] >> 11) & 0x7FF]++] = src[i];
+        std::swap(src, dst);
+    }
+
+    // Pass 3: bits 22-31
+    {
+        size_t pos[1024];
+        pos[0] = 0;
+        for (int i = 1; i < 1024; ++i) pos[i] = pos[i - 1] + c3[i - 1];
+        for (size_t i = 0; i < n; ++i) dst[pos[(src[i] >> 22) & 0x3FF]++] = src[i];
+        std::swap(src, dst);
+    }
+
+    if (src != a) {
+        std::memcpy(a, src, n * sizeof(uint32_t));
+    }
